const flowerSvg = (product, index) => {
  const [a,b,c] = palette[product.color];
  const petals = Array.from({length: 7}, (_,i) => {
    const x = 220 + Math.cos(i * .9) * (70 + (i%2)*35);
    const y = 180 + Math.sin(i * .9) * (55 + (i%3)*18);
    const r = 34 + (i%3)*8;
    return `<g transform="translate(${x.toFixed(0)} ${y.toFixed(0)}) rotate(${i*31})"><ellipse rx="${r}" ry="${r/2}" fill="${i%2?a:b}" opacity=".95"/><circle r="${r/4}" fill="${c}"/></g>`;
  }).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 620" role="img" aria-labelledby="t">
  <title id="t">${product.title}</title><rect width="520" height="620" rx="36" fill="#f4f1ec"/>
  <circle cx="${80+index*11}" cy="82" r="150" fill="${b}" opacity=".35"/><path d="M258 215 C230 320 205 385 176 505 M264 220 C292 322 320 390 346 500" fill="none" stroke="${c}" stroke-width="10" stroke-linecap="round"/>
  <path d="M224 345c-64-35-100 14-92 58 52 1 83-17 92-58ZM287 365c62-34 96 15 88 57-49 0-79-17-88-57Z" fill="${a}" opacity=".72"/>
  ${petals}<path d="M145 478 Q260 430 375 478 L342 570 H178Z" fill="${c}"/><path d="M166 487 Q260 530 354 487" fill="none" stroke="${b}" stroke-width="9" opacity=".6"/>
  </svg>`;
};

products.filter(product => product.image.endsWith(".svg")).forEach((product, index) => write(`assets/img/products/${product.image}`, flowerSvg(product,index)));

