const head = (title, file) => {
  const prefix = "../".repeat(file.split("/").length - 1);
  return { prefix, html:`<!doctype html><html lang="fa" dir="rtl" data-root="${prefix}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#60387b"><meta name="description" content="فلورا؛ فروشگاه آنلاین گل با انتخاب هوشمند، ارسال زمان‌بندی‌شده و تجربه‌ای ممتاز."><title>${title} | فلورا</title><link rel="stylesheet" href="${prefix}assets/vendor/estedad/index.css"><link rel="stylesheet" href="${prefix}assets/vendor/vazirmatn/index.css"><link rel="stylesheet" href="${prefix}assets/vendor/noto-sans-arabic/index.css"><link rel="stylesheet" href="${prefix}assets/vendor/lalezar/arabic.css"><link rel="stylesheet" href="${prefix}assets/vendor/bootstrap/bootstrap.rtl.min.css"><link rel="stylesheet" href="${prefix}assets/vendor/bootstrap-icons/bootstrap-icons.min.css"><link rel="stylesheet" href="${prefix}assets/vendor/swiper/swiper-bundle.min.css"><link rel="stylesheet" href="${prefix}assets/vendor/aos/aos.css"><link rel="stylesheet" href="${prefix}assets/vendor/glightbox/glightbox.min.css"><link rel="stylesheet" href="${prefix}assets/css/site.css"><script defer src="${prefix}assets/vendor/bootstrap/bootstrap.bundle.min.js"></script><script defer src="${prefix}assets/vendor/swiper/swiper-bundle.min.js"></script><script defer src="${prefix}assets/vendor/aos/aos.js"></script><script defer src="${prefix}assets/vendor/glightbox/glightbox.min.js"></script><script defer src="${prefix}assets/js/data.js"></script><script defer src="${prefix}assets/js/store.js"></script><script defer src="${prefix}assets/js/app.js"></script></head><body><site-header></site-header>`};
};
const page = (file,title,content,options={}) => {
  const h=head(title,file);
  const raw=typeof content==="function"?content(h.prefix):content;
  const resolved=products.reduce((html,product)=>html.replaceAll(`${product.id}.svg`,product.image),raw);
  const routeClass=`route-${file.replace(/\/index\.html$|\.html$/g,"").replaceAll("/","-")||"home"}`;
  write(file,`${h.html}<main id="main" class="${[routeClass,options.mainClass||""].join(" ").trim()}">${resolved}</main><site-footer></site-footer></body></html>`);
};
const stripEnd=(s)=>String(s??"").replace(/[.\u06D4]+$/u,"").trim();
const uiIconMap={"check-circle-2":"check-circle","leaf":"leaf","sun":"sun","gem":"gem","arrow-left":"arrow-left","quote":"quote","zap":"lightning-charge","search":"search","timer":"stopwatch","wand-sparkles":"magic","bike":"bicycle","heart":"heart","message-circle-heart":"chat-heart","sprout":"flower1","droplets":"droplet","glass-water":"cup-straw","gift":"gift","crown":"award","shield-check":"shield-check","clock-3":"clock","message-circle":"chat","flower-2":"flower2","package":"box-seam","shopping-basket":"basket","party-popper":"balloon","cake-slice":"cake2","calendar-heart":"calendar-heart","sparkles":"stars","hand-heart":"heart","calendar-check":"calendar-check","refresh-cw":"arrow-repeat","badge-check":"patch-check","headphones":"headphones"};
const uiIcon=name=>`<i class="bi bi-${uiIconMap[name]||name}" aria-hidden="true"></i>`;
const faStep=i=>["۰۱","۰۲","۰۳","۰۴","۰۵","۰۶","۰۷","۰۸","۰۹","۱۰"][i]||String(i+1);
const intro=(eyebrow,title,text,opts={})=>{
  const t=stripEnd(title);
  const lead=stripEnd(text);
  const crumb=opts.crumb||t;
  const pointItems=opts.points?.length?opts.points:[["flower2","گل تازه روزانه"],["truck","تحویل زمان‌بندی‌شده"],["shield-check","تضمین کیفیت"]];
  const points=`<div class="page-hero-points">${pointItems.map(([icon,label])=>`<span>${uiIcon(icon)} ${label}</span>`).join("")}</div>`;
  const aside=opts.aside?`<div class="page-hero-aside">${opts.aside}</div>`:"";
  return `<section class="page-hero${aside?" has-aside":""}"><div class="container"><nav class="page-breadcrumb" aria-label="مسیر صفحه"><a data-root-link>خانه</a><span>•</span><strong>${crumb}</strong></nav><div class="page-hero-grid"><div class="page-hero-copy"><span class="eyebrow">${eyebrow}</span><h1>${t}</h1>${lead?`<p>${lead}</p>`:""}${points}</div>${aside}</div></div></section>`;
};
const pageSection=(inner,opts={})=>`<section class="page-section${opts.className?" "+opts.className:""}"><div class="container">${inner}</div></section>`;
const pageHead=(eyebrow,title,text,extra="")=>`<div class="page-section-head"><div><span class="eyebrow">${eyebrow}</span><h2>${stripEnd(title)}</h2>${text?`<p>${stripEnd(text)}</p>`:""}</div>${extra}</div>`;
