page("product/index.html","محصول",p=>`<section class="page-section product-page-section"><div class="container" data-product-page></div></section><section class="page-section product-related-section"><div class="container"><div class="page-section-head"><div><span class="eyebrow">پیشنهادهای مرتبط</span><h2>انتخاب‌های نزدیک</h2><p>اگر این انتخاب را می‌پسندید، این‌ها هم نزدیک به همان لحن‌اند.</p></div><a class="home-products-link d-none d-md-inline-flex" href="${p}shop/index.html"><span>فروشگاه</span>${uiIcon("arrow-left")}</a></div><product-grid data-slider data-ids="muse,mini-rose,seasonal,cloud"></product-grid></div></section>`);
