page("cart/index.html","سبد خرید",p=>`${intro("مرحله اول","سبد خرید","تعداد، پیام و زمان پیشنهادی را پیش از پرداخت مرور کنید.",{points:[["basket","مرور اقلام"],["chat-heart","پیام کارت"],["clock","زمان تحویل"]]})}<section class="page-section"><div class="container"><div class="row g-5"><div class="col-lg-8" data-cart-lines></div><aside class="col-lg-4"><div class="surface p-4 order-summary"><h2 class="h5">خلاصه سفارش</h2><div class="d-flex justify-content-between py-2"><span>جمع محصولات</span><span data-subtotal></span></div><div class="d-flex justify-content-between py-2"><span>تخفیف</span><span data-discount></span></div><div class="d-flex justify-content-between py-2"><span>ارسال</span><span data-shipping></span></div><hr><div class="d-flex justify-content-between h5"><span>مبلغ نهایی</span><span data-total></span></div><form class="input-group my-4" data-coupon-form><input class="form-control" name="coupon" placeholder="کد تخفیف"><button class="btn btn-outline-premium">اعمال</button></form><a class="btn btn-dark w-100" data-cart-checkout href="${p}checkout/index.html">ادامه و تکمیل سفارش</a></div></aside></div></div></section>`);
page("checkout/index.html","تکمیل سفارش",p=>`${intro("پرداخت امن","تکمیل سفارش","اطلاعات تحویل فقط برای هماهنگی همین سفارش استفاده می‌شود.",{points:[["shield-check","پرداخت آزمایشی امن"],["truck","بازه واقعی"],["lock","بدون ذخیره کارت"]]})}<section class="page-section"><div class="container"><div class="checkout-steps mb-5"><div class="checkout-step">۱. گیرنده</div><div class="checkout-step">۲. تحویل و هدیه</div><div class="checkout-step">۳. پرداخت</div></div><form data-checkout><div class="row g-5"><div class="col-lg-8"><section class="checkout-panel"><h2 class="h4 mb-4">خریدار و گیرنده</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">نام خریدار</label><input class="form-control" name="buyerName" required autocomplete="name"></div><div class="col-md-6"><label class="form-label">شماره همراه</label><input class="form-control" name="buyerPhone" required inputmode="tel" pattern="[0-9۰-۹]{10,11}"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" id="otherRecipient"><label class="form-check-label" for="otherRecipient">گیرنده شخص دیگری است</label></div></div><div class="col-md-6"><label class="form-label">نام گیرنده</label><input class="form-control" name="recipientName" required></div><div class="col-md-6"><label class="form-label">شماره گیرنده</label><input class="form-control" name="recipientPhone" required inputmode="tel"></div><div class="col-12"><label class="form-label">نشانی</label><textarea class="form-control" name="address" required rows="3"></textarea></div></div><button type="button" class="btn btn-dark mt-4" data-next>ادامه</button></section><section class="checkout-panel" hidden><h2 class="h4 mb-4">زمان تحویل و هدیه</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">منطقه</label><select class="form-select" name="zone" required>${D.zones.map(z=>`<option value="${z.id}">${z.name}</option>`).join("")}</select></div><div class="col-md-6"><label class="form-label">تاریخ</label><input class="form-control" type="date" name="date" required></div><div class="col-md-6"><label class="form-label">بازه تحویل</label><select class="form-select" name="slot" required></select></div><div class="col-md-6"><label class="form-label">لحن کارت</label><select class="form-select" name="tone"><option>صمیمی</option><option>رسمی</option><option>بدون نام فرستنده</option></select></div><div class="col-12"><label class="form-label">پیام کارت</label><textarea class="form-control" name="message" maxlength="180"></textarea></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="substitution" value="approved"> در صورت نیاز، جایگزینی هم‌ارزش با هماهنگی من انجام شود.</label></div></div><div class="d-flex gap-2 mt-4"><button type="button" class="btn btn-outline-premium" data-prev>بازگشت</button><button type="button" class="btn btn-dark" data-next>ادامه</button></div></section><section class="checkout-panel" hidden><h2 class="h4 mb-4">پرداخت آزمایشی</h2><div class="surface p-4"><label class="form-label">روش پرداخت</label><label class="d-flex gap-2 py-2"><input class="form-check-input" type="radio" name="payment" value="gateway" checked> درگاه بانکی</label><label class="d-flex gap-2 py-2"><input class="form-check-input" type="radio" name="payment" value="wallet"> کیف پول سازمانی</label><p class="small text-secondary mt-3">این نسخه نمایشی است و هیچ تراکنش واقعی انجام نمی‌شود.</p></div><div class="d-flex gap-2 mt-4"><button type="button" class="btn btn-outline-premium" data-prev>بازگشت</button><button class="btn btn-premium" type="submit">ثبت سفارش</button></div></section></div><aside class="col-lg-4"><div class="surface p-4 order-summary"><h2 class="h5">مبلغ قابل پرداخت</h2><strong class="display-6" data-checkout-total></strong><p class="small text-secondary mt-3">هزینه ارسال بر اساس منطقه انتخابی به‌روز می‌شود.</p></div></aside></div></form></div></section>`);
page("order-success/index.html","سفارش ثبت شد",`<section class="section-space-lg text-center"><div class="container" data-order-success></div></section>`);
page("track/index.html","پیگیری سفارش",`${intro("شفاف تا لحظه تحویل","پیگیری سفارش","آخرین وضعیت آماده‌سازی و تحویل سفارش.",{points:[["stopwatch","وضعیت زنده"],["geo-alt","مسیر تحویل"],["chat","پشتیبانی سریع"]]})}<section class="page-section"><div class="container"><div class="row g-5"><div class="col-lg-7"><div class="timeline"><div class="timeline-item done"><h3 class="h6">سفارش ثبت شد</h3><p class="text-secondary">اطلاعات سفارش دریافت شده است.</p></div><div class="timeline-item active"><h3 class="h6">در حال آماده‌سازی</h3><p class="text-secondary">گل‌آرا در حال آماده‌کردن ترکیب شماست.</p></div><div class="timeline-item"><h3 class="h6">کنترل کیفیت</h3></div><div class="timeline-item"><h3 class="h6">تحویل به پیک</h3></div><div class="timeline-item"><h3 class="h6">تحویل به گیرنده</h3></div></div></div><div class="col-lg-5"><div class="surface p-4"><h2 class="h5">نیاز به کمک دارید؟</h2><p class="text-secondary">شماره سفارش را برای پشتیبانی ارسال کنید.</p><a class="btn btn-outline-premium" href="../help/contact/index.html">تماس با پشتیبانی</a></div></div></div></div></section>`);

page("gift-finder/index.html","راهنمای انتخاب هدیه",`${intro("راهنمای سه‌دقیقه‌ای","هدیه مناسب را پیدا کنید","چند پاسخ کوتاه، پیشنهادهایی قابل تحویل و متناسب با لحن شما.",{points:[["magic","۴ گام کوتاه"],["heart","متناسب با لحن"],["truck","قابل تحویل"]]})}<section class="page-section"><div class="container"><div class="progress mb-4" style="height:4px"><div class="progress-bar bg-dark" data-finder-progress></div></div><form class="surface p-4 p-lg-5" data-finder><div class="finder-step"><h2 class="h4 mb-4">برای چه کسی؟</h2><div class="row g-3">${D.recipients.map(x=>`<div class="col-6 col-lg-4 choice-card"><input id="r-${x}" type="radio" name="recipient" value="${x}"><label for="r-${x}">${x}</label></div>`).join("")}</div><button type="button" class="btn btn-dark mt-4" data-finder-next>ادامه</button></div><div class="finder-step"><h2 class="h4 mb-4">چه مناسبتی؟</h2><div class="row g-3">${D.occasions.slice(0,9).map(x=>`<div class="col-6 col-lg-4 choice-card"><input id="o-${x}" type="radio" name="occasion" value="${x}"><label for="o-${x}">${x}</label></div>`).join("")}</div><div class="d-flex gap-2 mt-4"><button type="button" class="btn btn-outline-premium" data-finder-prev>بازگشت</button><button type="button" class="btn btn-dark" data-finder-next>ادامه</button></div></div><div class="finder-step"><h2 class="h4">بودجه و زمان</h2><div class="row g-3 mt-2"><div class="col-md-6"><label class="form-label">حداکثر بودجه</label><select class="form-select" name="budget"><option>تا ۲ میلیون</option><option>۲ تا ۴ میلیون</option><option>بیش از ۴ میلیون</option></select></div><div class="col-md-6"><label class="form-label">زمان تحویل</label><select class="form-select" name="speed"><option>امروز</option><option>فردا</option><option>تاریخ دیگر</option></select></div></div><div class="d-flex gap-2 mt-4"><button type="button" class="btn btn-outline-premium" data-finder-prev>بازگشت</button><button class="btn btn-premium">دیدن پیشنهادها</button></div></div><div class="finder-step"><span class="eyebrow">پیشنهادهای فلورا</span><h2 class="h3 mt-2 mb-4">این انتخاب‌ها برای شما مناسب‌اند.</h2><div data-finder-results></div><button type="button" class="btn btn-link mt-4" data-finder-prev>تغییر پاسخ‌ها</button></div></form></div></section>`);
page("fast-delivery/index.html","ارسال فوری",p=>`${intro("ظرفیت زنده امروز","گل تازه، همین امروز به دست‌تان برسد","منطقه و تاریخ را مشخص کنید تا فقط محصولاتی نمایش داده شوند که واقعاً برای ارسال امروز آماده‌اند؛ بدون وعده مبهم",{crumb:"ارسال فوری",points:[["lightning-charge","آماده‌سازی زیر ۹۰ دقیقه"],["geo-alt","پوشش تهران"],["shield-check","تضمین تازگی"]],aside:`<div class="page-panel" id="fastCapacity"><div class="page-panel-head"><span class="page-panel-icon">${uiIcon("stopwatch")}</span><div><strong>بررسی ظرفیت ارسال</strong><small>ابتدا امکان تحویل را بسنجید، بعد انتخاب کنید</small></div></div><form class="page-panel-form" data-success-form="ظرفیت بررسی شد؛ بازه ۱۵ تا ۱۸ امروز در دسترس است."><div class="page-field"><label class="form-label" for="fastZone">منطقه تحویل</label><div class="page-control">${uiIcon("geo-alt")}<select class="form-select" id="fastZone" required>${D.zones.map(z=>`<option value="${z.id}">${z.name}</option>`).join("")}</select></div></div><div class="page-field"><label class="form-label" for="fastDate">تاریخ تحویل</label><div class="page-control">${uiIcon("calendar3")}<input class="form-control" id="fastDate" type="date" required></div></div><button class="btn btn-premium page-panel-cta" type="submit"><span>مشاهده ظرفیت امروز</span>${uiIcon("arrow-left")}</button></form></div>`})}${pageSection(`${pageHead("منتخب فوری","آماده ارسال امروز","این محصولات برای بازه‌های نزدیک واجد شرایط‌اند و می‌توانید همین حالا سفارش دهید.",`<a class="home-products-link d-none d-md-inline-flex" href="${p}shop/index.html"><span>همه محصولات</span>${uiIcon("arrow-left")}</a>`)}<product-grid data-ids="aurora,muse,mini-rose,seasonal"></product-grid>`)}`);

page("corporate/index.html","خدمات سازمانی",p=>`${intro("فلورا برای تیم‌ها","هدیه سازمانی، بدون آشفتگی عملیاتی","از یک سفارش ویژه تا ارسال چندگیرنده‌ای با بودجه، برندینگ و تأیید داخلی.",{crumb:"خدمات سازمانی",points:[["buildings","چندگیرنده"],["wallet2","کنترل بودجه"],["patch-check","مسیر تأیید"]],aside:`<div class="page-panel corp-journey"><div class="page-panel-head"><span class="page-panel-icon">${uiIcon("buildings")}</span><div><strong>مسیر سفارش سازمانی</strong><small>چهار گام کوتاه تا تحویل هماهنگ</small></div></div><ol class="corp-journey-list"><li class="corp-journey-step"><span class="corp-journey-index">${faStep(0)}</span><span class="corp-journey-icon">${uiIcon("sliders")}</span><div class="corp-journey-copy"><strong>پیکربندی</strong><small>محصول، بسته‌بندی، بودجه و پیام</small></div></li><li class="corp-journey-step"><span class="corp-journey-index">${faStep(1)}</span><span class="corp-journey-icon">${uiIcon("people")}</span><div class="corp-journey-copy"><strong>گیرندگان</strong><small>ورود دستی یا فایل گروهی</small></div></li><li class="corp-journey-step"><span class="corp-journey-index">${faStep(2)}</span><span class="corp-journey-icon">${uiIcon("file-earmark-check")}</span><div class="corp-journey-copy"><strong>تأیید</strong><small>پیش‌فاکتور و مسیر تأیید</small></div></li><li class="corp-journey-step"><span class="corp-journey-index">${faStep(3)}</span><span class="corp-journey-icon">${uiIcon("truck")}</span><div class="corp-journey-copy"><strong>تحویل</strong><small>پیگیری استثناها و گزارش نهایی</small></div></li></ol><a class="btn btn-premium page-panel-cta" href="${p}corporate/configure/index.html"><span>ساخت درخواست</span>${uiIcon("arrow-left")}</a></div>`})}${pageSection(`<div class="corp-cta surface-soft"><div class="corp-cta-copy"><span class="eyebrow">شروع آرام</span><h2>سفارش سازمانی بعدی را طراحی کنید</h2><p>پاسخ اولیه در نسخه نمایشی بلافاصله ساخته می‌شود؛ بدون پیچیدگی عملیاتی.</p></div><a class="btn btn-dark" href="${p}corporate/configure/index.html">رفتن به پیکربندی</a></div>`)}`);

page("corporate/configure/index.html","پیکربندی سازمانی",p=>`${intro("درخواست قیمت","پیکربندی سفارش سازمانی","جزئیات عملیاتی را ثبت کنید تا یک درخواست قابل پیگیری ساخته شود.",{points:[["file-earmark-text","پیش‌فاکتور"],["people","لیست گیرندگان"],["calendar3","بازه تحویل"]]})}<section class="page-section"><div class="container"><form class="surface p-4 p-lg-5" data-quote-form><div class="row g-3"><div class="col-md-6"><label class="form-label">نام سازمان</label><input class="form-control" name="company" required></div><div class="col-md-6"><label class="form-label">نام درخواست‌کننده</label><input class="form-control" name="requester" required></div><div class="col-md-4"><label class="form-label">تعداد</label><input class="form-control" type="number" min="5" name="quantity" required></div><div class="col-md-4"><label class="form-label">بودجه هر هدیه</label><input class="form-control" type="number" name="budget" required></div><div class="col-md-4"><label class="form-label">بازه تحویل</label><input class="form-control" type="date" name="date" required></div><div class="col-md-6"><label class="form-label">نوع محصول</label><select class="form-select" name="product">${D.categories.map(x=>`<option>${x}</option>`).join("")}</select></div><div class="col-md-6"><label class="form-label">برندینگ</label><select class="form-select" name="branding"><option>بدون برندینگ</option><option>کارت اختصاصی</option><option>بسته‌بندی اختصاصی</option></select></div><div class="col-12"><label class="form-label">گیرندگان</label><input class="form-control" type="file" accept=".csv" aria-describedby="csvHelp"><div class="form-text" id="csvHelp">برای نمایش جریان کار؛ فایل به سرور ارسال نمی‌شود.</div></div><div class="col-12"><label class="form-label">توضیحات</label><textarea class="form-control" rows="4"></textarea></div></div><button class="btn btn-premium mt-4">ثبت درخواست قیمت</button></form></div></section>`);
page("corporate/quote-success/index.html","درخواست ثبت شد",`${intro("درخواست دریافت شد","پیش‌فاکتور در حال آماده‌سازی است.",'شناسه درخواست شما <strong data-quote-success>FL-Q-1405</strong> است.')}<section class="page-section text-center"><a class="btn btn-dark" href="../../account/index.html">مشاهده داشبورد</a></section>`);

const accountWrap=(title,body)=>`${intro("حساب فلورا",title,"سفارش‌ها، گیرندگان و یادآورها در یک فضای آرام و ساده.",{points:[["bag-check","پیگیری سفارش"],["people","گیرندگان ذخیره‌شده"],["bell","یادآور مناسبت"]]})}<section class="page-section"><div class="container"><div class="account-shell"><account-nav></account-nav><div>${body}</div></div></div></section>`;
page("auth/index.html","ورود و عضویت",`${intro("حساب کاربری","خوش آمدید","برای ذخیره سفارش‌ها و گیرندگان وارد شوید یا حساب نمایشی بسازید.",{points:[["person","ورود سریع"],["shield-check","نمایشی و امن"],["heart","ذخیره علاقه‌مندی"]]})}<section class="page-section"><div class="container"><div class="row g-4"><div class="col-lg-6"><form class="surface p-4" data-auth-form><h2 class="h4">ورود</h2><label class="form-label mt-3">ایمیل یا شماره همراه</label><input class="form-control" name="identity" required><label class="form-label mt-3">گذرواژه</label><input class="form-control" type="password" name="password" required minlength="6"><div class="d-flex justify-content-between mt-3"><label><input type="checkbox"> مرا به خاطر بسپار</label><a href="forgot/index.html">بازیابی</a></div><button class="btn btn-dark w-100 mt-4">ورود</button></form></div><div class="col-lg-6"><form class="surface p-4" data-auth-form><h2 class="h4">ساخت حساب</h2><label class="form-label mt-3">نام</label><input class="form-control" name="name" required><label class="form-label mt-3">ایمیل</label><input class="form-control" type="email" name="email" required><label class="form-label mt-3">گذرواژه</label><input class="form-control" type="password" name="password" required minlength="8"><button class="btn btn-premium w-100 mt-4">عضویت</button></form></div></div></div></section>`);
page("auth/forgot/index.html","بازیابی گذرواژه",`${intro("بازیابی","دسترسی دوباره به حساب","لینک بازیابی به ایمیل یا شماره ثبت‌شده ارسال می‌شود.")}<section class="page-section"><div class="container" style="max-width:640px"><form class="surface p-4" data-success-form="راهنمای بازیابی ارسال شد."><label class="form-label">ایمیل یا شماره همراه</label><input class="form-control" required><button class="btn btn-dark mt-3">ارسال راهنما</button></form></div></section>`);
page("account/index.html","داشبورد",accountWrap("نمای کلی",`<div class="row g-3"><div class="col-md-4"><div class="metric"><small>سفارش فعال</small><strong class="d-block">۱</strong></div></div><div class="col-md-4"><div class="metric"><small>گیرنده ذخیره‌شده</small><strong class="d-block">۳</strong></div></div><div class="col-md-4"><div class="metric"><small>یادآور نزدیک</small><strong class="d-block">۲</strong></div></div></div><div class="surface p-4 mt-4"><span class="eyebrow">اقدام بعدی</span><h2 class="h4 mt-2">تولد نیلوفر، ۱۲ روز دیگر</h2><p class="text-secondary">می‌توانید هدیه را حالا انتخاب و برای همان روز زمان‌بندی کنید.</p><a class="btn btn-dark" href="../gift-finder/index.html">انتخاب هدیه</a></div>`));
page("account/orders/index.html","سفارش‌ها",accountWrap("سفارش‌های من",`<div data-orders-list></div>`));
